// Reference JS/BigInt reimplementation of bech32_hrp_expand + bech32_polymod
const GEN = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

function hrpExpand(hrp) {
  const cps = [...hrp].map(c => c.codePointAt(0));
  return cps.map(c => c >> 5).concat([0], cps.map(c => c & 31));
}

function polymod(values) {          // values: BigInt[]
  let chk = 1n;
  for (const v of values) {
    const top = chk >> 25n;
    chk = ((chk & 0x1ffffffn) << 5n) ^ v;
    for (let i = 0n; i < 5n; i++) {
      if ((top >> i) & 1n) chk ^= GEN[Number(i)];
    }
  }
  return chk;
}

const hrp = process.argv[2];
const bstr = process.argv[3];
const data = bstr.split(',').map(s => BigInt(s));       // mimic int() for plain ints
const he = hrpExpand(hrp);
const combined = he.map(BigInt).concat(data);
console.log('[' + he.join(', ') + ']');                  // Python list repr
console.log(polymod(combined).toString());
EOF
